async function library(mode='library'){const root=$('#app');try{const me=await api('/api/me');if(!me.user){root.innerHTML=pageStart('My Library','Sign in to save stories and sync your reading across devices.')+`<div class="panel"><p>Your library is available after signing in.</p><a class="primary" href="/login">Sign In</a><a class="secondary" href="/register">Create Account</a></div></div></div>`;return}const [items,historyRows,bookmarks,following]=await Promise.all([api('/api/library'),api('/api/history'),api('/api/bookmarks'),api('/api/follows')]);const active=mode==='following'?'following':'library';root.innerHTML=pageStart('My Library','Your saved stories, reading progress and bookmarks, synced to your account.')+`<div class="tabs"><a class="${active==='library'?'active':''}" href="/library">My Library</a><a href="/history">History</a><a class="${active==='following'?'active':''}" href="/following">Following</a></div><section class="section"><div class="sectionHead"><div><h2>Continue Reading</h2><p>Jump back into your most recently read stories.</p></div></div><div class="grid" id="continueList"></div></section><section class="section"><div class="sectionHead"><div><h2>Saved Stories</h2><p>${items.length} novel${items.length===1?'':'s'} in your library.</p></div></div><div class="grid" id="savedList"></div></section><section class="section"><div class="sectionHead"><div><h2>Bookmarked Chapters</h2><p>Your saved chapter positions.</p></div></div><div id="bookmarkList" class="panel"></div></section></div></div>`;const cont=historyRows.slice(0,12);$('#continueList').innerHTML=cont.length?cont.map(x=>`<article class="panel"><div class="muted">${esc(x.author||'Unknown author')}</div><h3>${esc(x.title)}</h3><p>Chapter ${Number(x.chapter_number)}</p><a class="primary" href="/read/${x.novel_id}/${Number(x.chapter_number)}">Continue Reading →</a></article>`).join(''):`<div class="empty" style="grid-column:1/-1">No reading history yet. Open a chapter to begin.</div>`;$('#savedList').innerHTML=items.length?items.map(x=>`<article class="card"><a href="/novel/${x.novel_id}"><div class="cover"><img src="${img(x.cover_url)}" alt="${esc(x.title)} cover" loading="lazy" decoding="async" fetchpriority="low"></div><div class="cardBody"><div class="cardTitle">${esc(x.title)}</div><div class="muted">${esc(x.author||'Unknown author')}</div><div class="meta"><span>★ ${Number(x.rating||0).toFixed(1)}</span><span>${x.latest_chapter?`${Number(x.latest_chapter)} ch.`:'No chapters'}</span></div></div></a><div style="padding:0 13px 13px"><button class="ghost removeLibrary" data-id="${x.novel_id}" type="button">Remove from Library</button></div></article>`).join(''):`<div class="empty" style="grid-column:1/-1">Your library is empty. Open a novel and tap <b>Add to Library</b>.</div>`;$('#bookmarkList').innerHTML=bookmarks.length?bookmarks.map(x=>`<div class="statline"><span><b>${esc(x.title)}</b> · Chapter ${Number(x.chapter_number)}</span><a class="ghost" href="/read/${x.novel_id}/${Number(x.chapter_number)}">Open</a></div>`).join(''):`<div class="empty">No bookmarked chapters yet.</div>`;$$('.removeLibrary').forEach(b=>b.onclick=async()=>{try{await api('/api/library',{method:'POST',body:JSON.stringify({novel_id:Number(b.dataset.id)})});b.closest('.card')?.remove()}catch(e){alert(e.message)}})}catch(e){root.innerHTML=pageStart('My Library')+`<div class="notice">${esc(e.message)} <a href="/login" style="color:var(--gold2)">Sign in</a></div></div></div>`}}
