 form.onsubmit=async ev=>{ev.preventDefault();const fd=new FormData(form),payload=Object.fromEntries(fd.entries());payload.title=String(payload.title||'').trim();payload.description=String(payload.description||'').trim();payload.rights_evidence=String(payload.rights_evidence||'').trim();payload.rights_notes=String(payload.rights_notes||'').trim();if(payload.rights_status!=='original'&&!payload.rights_evidence){setNotice('Please provide rights evidence for public-domain, licensed, or authorized works.',true);return}const b=$('button[type="submit"]',form);b.disabled=true;try{const d=await api('/api/author/novels',{method:'POST',body:JSON.stringify(payload)});storyLocalDraft.clear();setNotice(d.message||'Draft created.');form.reset();await loadWorks()}catch(e){setNotice(e.message||'Could not create the draft. Sign in with an author account and try again.',true)}finally{b.disabled=false}};
