 $('#authorNoteForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type="submit"]',form),story=Number($('#authorNoteStory').value),chapter=Number($('#authorNoteChapter').value)||null,note=$('#authorNoteText').value;button.disabled=true;try{await api('/api/author/notes',{method:'POST',body:JSON.stringify({novel_id:story,chapter_id:chapter,note})});$('#authorNoteText').value='';$('#authorNoteChapter').value='';setNotice('Private note saved.');await loadAuthorNotes()}catch(error){setNotice(error.message||'Could not save private note.',true)}finally{button.disabled=false}};
