async function authorPublic(){const slug=decodeURIComponent(location.pathname.split('/').pop()||'').trim();const root=$('#app');root.innerHTML=pageStart('Author Profile','Published stories and public catalog activity.')+`<div id="authorProfile" class="panel">Loading author profile...</div></div></div>`;try{const d=await api('/api/novels?author='+encodeURIComponent(slug)+'&limit=50');const rows=d.results||[];if(!rows.length){$('#authorProfile').innerHTML=`<div class="empty"><h2>Author not found</h2><p>No published stories are currently associated with <b>${esc(slug)}</b>.</p><a class="primary" href="/catalog">Browse the Catalog</a></div>`;return}const author=rows[0].author||slug;$('#authorProfile').innerHTML=`<div class="authorHero"><div class="authorAvatar">♛</div><div><div class="eyebrow">PUBLIC AUTHOR</div><h2>${esc(author)}</h2><p>${rows.length} published ${rows.length===1?'story':'stories'} in the Imperial catalog.</p></div></div><div class="section"><div class="sectionHead"><div><h2>Published Stories</h2><p>Explore this author's available works.</p></div></div><div class="grid">${rows.map(card).join('')}</div></div>`}catch(e){$('#authorProfile').innerHTML=`<div class="notice">${esc(e.message||'Unable to load this author profile.')} <a href="/catalog">Return to Catalog</a></div>`}}
function settings(){const root=$('#app'),get=(k,d)=>localStorage.getItem(k)??d;root.innerHTML=pageStart('Settings','Make Imperial Novel yours. Preferences are saved on this device.')+`<section class="settingsGrid settingsGridPro"><div class="panel settingsPanel"><div class="eyebrow">YOUR INTERFACE</div><h2>Appearance & Reading</h2><div class="settingRow"><div><b>Site theme</b><small>Choose your overall interface.</small></div><select id="setSiteTheme"><option value="dark">Midnight</option><option value="light">Light</option></select></div><div class="settingRow"><div><b>Reader theme</b><small>Six distinct reading canvases.</small></div><select id="setReaderTheme"><option value="light">Paper</option><option value="dark">Dark</option><option value="midnight">Midnight</option><option value="sepia">Sepia</option><option value="imperial">Imperial</option><option value="cosmic">Cosmic</option></select></div><div class="settingRow"><div><b>Chapter text size</b><small>Adjust the reader's typography.</small></div><input id="setFont" type="range" min="15" max="30" value="${esc(get('readerSize',get('imperial_font_size','18')))}"><output id="fontOut">${esc(get('readerSize',get('imperial_font_size','18')))}px</output></div><div class="settingRow"><div><b>Line spacing</b><small>Compact, comfortable or relaxed.</small></div><select id="setLine"><option value="1.65">Compact</option><option value="1.85">Comfort</option><option value="2">Relaxed</option></select></div><div class="settingRow"><div><b>Text width</b><small>Choose your reading column.</small></div><select id="setWidth"><option value="500">Focused</option><option value="600">Standard</option><option value="680">Wide</option></select></div></div><div class="panel settingsPanel"><div class="eyebrow">ACCESSIBILITY</div><h2>Comfort & Control</h2><label class="checkRow"><input id="setReduced" type="checkbox" ${get('imperial_reduced_motion','false')==='true'?'checked':''}><span><b>Reduce motion</b><small>Minimize animation and transitions.</small></span></label><label class="checkRow"><input id="setHigh" type="checkbox" ${get('imperial_high_contrast','false')==='true'?'checked':''}><span><b>High contrast</b><small>Improve text and control separation.</small></span></label><label class="checkRow"><input id="setCompact" type="checkbox" ${get('imperial_compact_cards','false')==='true'?'checked':''}><span><b>Compact novel cards</b><small>Fit more discoveries on smaller screens.</small></span></label><div class="notice settingsNotice" id="settingsSaved" role="status" aria-live="polite" hidden>Preferences saved.</div></div><div class="panel settingsPanel"><div class="eyebrow">DATA & PORTABILITY</div><h2>Your preferences, your choice</h2><p class="muted">Export your local preferences or clear locally stored reading helpers. Clearing local helpers does not delete server-synced account data.</p><div class="actions settingsActions"><button class="primary" id="exportPrefs" type="button">Export preferences</button><button class="secondary" id="resetPrefs" type="button">Reset preferences</button><button class="secondary" id="clearLocalReading" type="button">Clear local reading data</button></div></div><div class="panel settingsPanel"><div class="eyebrow">ACCOUNT & COMMUNITY</div><h2>Your Imperial account</h2><div class="actions settingsActions"><a class="primary" href="/account">Account center</a><a class="secondary" href="/notifications">Notifications</a><a class="secondary" href="/library">My library</a><a class="secondary" href="/author">Author Studio</a></div></div></section></div></div>`;$('#setSiteTheme').value=document.documentElement.dataset.theme==='light'?'light':'dark';$('#setReaderTheme').value=get('imperial_reader_theme','dark');$('#setLine').value=get('imperial_reader_line_height',get('imperial_line_height','1.85'));$('#setWidth').value=get('imperial_reader_width','600');const note=m=>{const n=$('#settingsSaved');n.textContent=m;n.hidden=false;clearTimeout(window.__settingsTimer);window.__settingsTimer=setTimeout(()=>n.hidden=true,2200)};const save=()=>{const size=$('#setFont').value,lh=$('#setLine').value,w=$('#setWidth').value;try{[['imperial_theme',$('#setSiteTheme').value],['imperial_reader_theme',$('#setReaderTheme').value],['readerSize',size],['imperial_font_size',size],['imperial_reader_line_height',lh],['imperial_line_height',lh],['imperial_reader_width',w],['imperial_reduced_motion',String($('#setReduced').checked)],['imperial_high_contrast',String($('#setHigh').checked)],['imperial_compact_cards',String($('#setCompact').checked)]].forEach(([k,v])=>localStorage.setItem(k,v))}catch(e){note('Browser storage is unavailable.');return}document.documentElement.dataset.theme=$('#setSiteTheme').value;document.documentElement.dataset.reducedMotion=$('#setReduced').checked?'true':'false';document.documentElement.dataset.highContrast=$('#setHigh').checked?'true':'false';document.documentElement.dataset.compactCards=$('#setCompact').checked?'true':'false';$('#fontOut').textContent=size+'px';note('Preferences saved on this device.')};['#setSiteTheme','#setReaderTheme','#setFont','#setLine','#setWidth','#setReduced','#setHigh','#setCompact'].forEach(s=>$(s)?.addEventListener('input',save));$('#exportPrefs').onclick=()=>{const keys=['imperial_theme','imperial_reader_theme','readerSize','imperial_font_size','imperial_reader_line_height','imperial_line_height','imperial_reader_width','imperial_reduced_motion','imperial_high_contrast','imperial_compact_cards'];const data={product:'Imperial Novel',format:1,exportedAt:new Date().toISOString(),preferences:Object.fromEntries(keys.filter(k=>localStorage.getItem(k)!==null).map(k=>[k,localStorage.getItem(k)]))};const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),el=document.createElement('a');el.href=u;el.download='imperial-novel-preferences.json';el.click();setTimeout(()=>URL.revokeObjectURL(u),1000);note('Preference export prepared.')};$('#resetPrefs').onclick=()=>{if(!confirm('Reset appearance and reader preferences on this device?'))return;['imperial_theme','imperial_reader_theme','readerSize','imperial_font_size','imperial_reader_line_height','imperial_line_height','imperial_reader_width','imperial_reduced_motion','imperial_high_contrast','imperial_compact_cards'].forEach(k=>localStorage.removeItem(k));location.reload()};$('#clearLocalReading').onclick=()=>{if(!confirm('Clear local reading progress and bookmark helpers? Server account data will not be deleted.'))return;Object.keys(localStorage).filter(k=>/^(readerProgress:|readerProgressChapter:|readerBookmark:)/.test(k)).forEach(k=>localStorage.removeItem(k));note('Local reading helpers cleared.')};}

async function boot(){const root=document.querySelector('#app')||document.createElement('main');root.id='app';root.className='appBootRoot';root.innerHTML='<section class="bootFallback" role="status"><div class="bootCrest" aria-hidden="true">IN</div><p class="bootEyebrow">IMPERIAL NOVEL</p><h1>Your next world is loading.</h1><p>Preparing your storyverse…</p><span class="bootSpinner" aria-hidden="true"></span></section>';if(!document.body.contains(root))document.body.appendChild(root);try{shell();const p=location.pathname;const titles={'/':'Home','/discover':'Discover','/community':'Community','/leaderboard':'Leaderboard','/tier-list':'Tier List','/random':'Random Novel','/made-for-you':'Made For You','/for-you':'Made For You','/trending':'Trending Now','/vote':'Vote Novels','/notifications':'Notifications','/settings':'Settings','/omniportal':'OmniPortal','/author':'Author Studio','/admin':'Command Center','/trend-factory':'Trend Factory'};if(titles[p])document.title=titles[p]+' | Imperial Novel';if(p==='/')await home();else if(p==='/trend-factory')await trendFactory();else if(p==='/discover'||p==='/catalog')await catalog();else if(p==='/formats')await formatDirectory();else if(/^\/format\/[^/]+\/?$/.test(p))await formatLanding(decodeURIComponent(p.split('/')[2]||''));else if(p==='/genres')await genres();else if(p==='/tags')await tags();else if(p==='/search')await search();else if(/^\/novel\/\d+\/chapters\/?$/.test(p))await chapters();else if(/^\/novel\/\d+\/?$/.test(p))await novel();else if(/^\/read\/\d+\/\d+\/?$/.test(p))await reader();else if(p==='/library')await library();else if(p==='/history')await history();else if(p==='/following')await following();else if(p==='/tickets')await tickets();else if(p==='/requests')await requests();else if(p==='/omniportal')await omni();else if(p==='/community')await discoveryPage('community');else if(p==='/leaderboard')await discoveryPage('leaderboard');else if(p==='/tier-list')await discoveryPage('tier-list');else if(p==='/random')await discoveryPage('random');else if(p==='/made-for-you'||p==='/for-you')await discoveryPage('made-for-you');else if(p==='/trending')await discoveryPage('trending');else if(p==='/vote')await discoveryPage('vote');else if(p==='/notifications')await discoveryPage('notifications');else if(p==='/settings')settings();else if(p==='/author')await authorStudio();else if(p==='/account')await account();else if(p==='/login')await authPage('login');else if(p==='/register')await authPage('register');else if(p.startsWith('/fandom/')){const slug=p.split('/').pop();location.href='/catalog?tag='+encodeURIComponent(slug)}else if(/^\/author\/[^/]+$/.test(p))await authorPublic();else simplePage('Page not found','The page you requested does not exist.');}catch(e){console.error('Imperial Novel boot failed',e);root.innerHTML=`<section class="bootFallback bootFailure" role="alert"><div class="bootCrest" aria-hidden="true">IN</div><p class="bootEyebrow">IMPERIAL NOVEL</p><h1>We hit a loading snag.</h1><p>${esc(e&&e.message||'The page could not finish loading.')}</p><button class="btn primary" onclick="location.reload()">Try again</button><p class="bootHelp">If this repeats, close this tab and reopen Imperial Novel.</p></section>`}}
boot();
